from pathlib import Path
import re
unused=[line.strip().split('.',1)[1] for line in Path('/tmp/unused_loop.txt').read_text().splitlines() if line.startswith('en.')]
# Never remove the deliberately ignored generic key; it shouldn't appear.
to_remove={'en.'+k for k in unused if k != 'flash.actions.create.notice'}
cfg=Path('config/i18n-tasks.yml').read_text(); files=[]
for mt in re.finditer(r'^\s*- (config/locales/%\{locale\}/[^\s]+\.yml)\s*$', cfg, re.M):
    p=mt.group(1).replace('%{locale}','en')
    if Path(p).exists() and p not in files: files.append(p)
def prune(path, remove_set):
    lines=path.read_text().splitlines(keepends=True); stack=[]; out=[]; i=0; removed=0
    while i < len(lines):
        line=lines[i]; stripped=line.strip()
        if not stripped or stripped.startswith('#'):
            out.append(line); i+=1; continue
        indent=len(line)-len(line.lstrip(' '))
        while stack and indent <= stack[-1][0]: stack.pop()
        m=re.match(r'^(\s*)(?:["\']?)([^"\'#][^:]*?)(?:["\']?):(?:\s|$)', line)
        if m:
            key=m.group(2).strip(); full='.'.join([s[1] for s in stack]+[key])
            if full in remove_set:
                i+=1
                while i < len(lines):
                    nxt=lines[i]
                    if not nxt.strip(): i+=1; continue
                    if (len(nxt)-len(nxt.lstrip(' '))) > indent: i+=1; continue
                    break
                removed+=1; continue
